415	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
416	func (s *state) validate() error {
417		if s.Version != stateVersion {
418			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
419		}
420		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
421			return errors.New("缺少必要的数据节")
422		}
423		for id, p := range s.Plans {
424			if p == nil {
425				return fmt.Errorf("方案 %q 的数据为空", id)
426			}
427			if p.ID != id {
428				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
429			}
430			if err := validatePlanRules(p); err != nil {
431				return err
432			}
433		}
434		for id, c := range s.Customers {
435			if c == nil {
436				return fmt.Errorf("客户 %q 的数据为空", id)
437			}
438			if c.ID != id {
439				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
440			}
441			if c.ID == "" || c.Name == "" {
442				return fmt.Errorf("客户 %q 的标识或名称为空", id)
443			}
444			if c.Price < 0 {
445				return fmt.Errorf("客户 %q 单价为负", id)
446			}
447			if c.PlanID != "" {
448				if _, ok := s.Plans[c.PlanID]; !ok {
449					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
450				}
451			}
452		}
453		// 方案变更：键、客户（须为绑定阶梯方案的客户）、目标方案、生效月与
454		// 原因都必须自洽；同一客户的变更生效月由键保证唯一。
455		for key, ch := range s.PlanChanges {
456			if ch == nil {
457				return fmt.Errorf("方案变更 %q 的数据为空", key)
458			}
459			if planChangeKey(ch.CustomerID, ch.Month) != key {
460				return fmt.Errorf("方案变更键不一致: 键 %q / 客户月份 %s|%s", key, ch.CustomerID, ch.Month)
461			}
462			c, ok := s.Customers[ch.CustomerID]
463			if !ok {
464				return fmt.Errorf("方案变更 %q 引用了不存在的客户 %q", key, ch.CustomerID)
465			}
466			if c.PlanID == "" {
467				return fmt.Errorf("方案变更 %q 的客户 %q 未绑定阶梯方案", key, ch.CustomerID)
468			}
469			if !validMonth(ch.Month) {
470				return fmt.Errorf("方案变更 %q 的生效月无效", key)
471			}
472			if _, ok := s.Plans[ch.PlanID]; !ok {
473				return fmt.Errorf("方案变更 %q 引用了不存在的方案 %q", key, ch.PlanID)
474			}
475			if strings.TrimSpace(ch.Reason) == "" {
476				return fmt.Errorf("方案变更 %q 的原因为空", key)
477			}
478		}
479		// 方案变更撤销登记：键与客户/目标生效月一致；引用的目标变更必须存在
480		// （失效撤销引用即损坏）；撤销原因非空。原变更内容、原原因与撤销记录都
481		// 永久保留，撤销不可撤销。旧文件缺少撤销记录时全部变更视为有效
482		// （PlanChangeRevocations 已在载入时补为空表）。账单方案与撤销后有效
483		// 安排的一致性由阶梯账单校验（validateTieredBill）把关。
484		for key, rv := range s.PlanChangeRevocations {
485			if rv == nil {
486				return fmt.Errorf("方案变更撤销 %q 的数据为空", key)
487			}
488			if planChangeKey(rv.CustomerID, rv.Month) != key {
489				return fmt.Errorf("方案变更撤销键不一致: 键 %q / 客户月份 %s|%s", key, rv.CustomerID, rv.Month)
490			}
491			if _, ok := s.PlanChanges[key]; !ok {
492				return fmt.Errorf("方案变更撤销 %q 引用了不存在的方案变更（客户 %q 生效月 %q，撤销目标失效）",
493					key, rv.CustomerID, rv.Month)
494			}
495			if !validMonth(rv.Month) {
496				return fmt.Errorf("方案变更撤销 %q 的目标生效月无效", key)
497			}
498			if strings.TrimSpace(rv.Reason) == "" {
499				return fmt.Errorf("方案变更撤销 %q 的原因为空", key)
500			}
501		}
502		for id, u := range s.Usage {
503			if u == nil {
504				return fmt.Errorf("用量 %q 的数据为空", id)
505			}
506			if u.ID != id {
507				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
508			}
509			if u.ID == "" {
510				return errors.New("存在空的用量标识")
511			}
512			if _, ok := s.Customers[u.CustomerID]; !ok {
513				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
514			}
515			if u.Quantity <= 0 {
516				return fmt.Errorf("用量 %q 的数量非正", u.ID)
517			}
518			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
519				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
520			}
521		}
522		// 撤回标记：键与记录一致、目标用量存在（撤回目标失效即损坏）、原因非空。
523		// 原用量记录仍按上面的规则完整校验（格式、正数量、客户存在性），撤回不
524		// 删除或改写原记录。旧文件缺少撤回记录视为全部用量有效（Withdrawals 已
525		// 在载入时补为空表）。
526		for id, w := range s.Withdrawals {
527			if w == nil {
528				return fmt.Errorf("用量 %q 的撤回记录为空", id)
529			}
530			if w.UsageID != id {
531				return fmt.Errorf("撤回记录键不一致: 键 %q / 用量标识 %q", id, w.UsageID)
532			}
533			if w.UsageID == "" {
534				return errors.New("存在空用量标识的撤回记录")
535			}
536			if _, ok := s.Usage[w.UsageID]; !ok {
537				return fmt.Errorf("撤回记录引用了不存在的用量 %q（撤回目标失效）", w.UsageID)
538			}
539			if strings.TrimSpace(w.Reason) == "" {
540				return fmt.Errorf("用量 %q 的撤回原因为空", w.UsageID)
541			}
542		}
543		// 用量更正关联：键与原标识一致；原记录与替代记录都必须存在于 Usage，
544		// 替代记录内容（客户、解析后的时间点、数量）须与更正保存的新内容一致；
545		// 原记录必须已按更正原因撤回（撤回标记的原因与更正原因不符即损坏）；
546		// 同一替代记录只能有一个来源；关联不得成环。替代记录后来被合法撤回或
547		// 继续更正（即它本身又作为某条更正的原记录）属正常状态，不判为损坏。
548		// 旧文件缺少更正记录视为无更正（UsageCorrections 已在载入时补为空表）。
549		replacementSources := make(map[string]string) // 替代用量标识 -> 原用量标识
550		for id, uc := range s.UsageCorrections {
551			if uc == nil {
552				return fmt.Errorf("用量更正 %q 的数据为空", id)
553			}
554			if uc.UsageID != id {
555				return fmt.Errorf("用量更正键不一致: 键 %q / 原用量标识 %q", id, uc.UsageID)
556			}
557			if uc.UsageID == "" {
558				return errors.New("存在空原用量标识的更正记录")
559			}
560			if strings.TrimSpace(uc.Reason) == "" {
561				return fmt.Errorf("用量更正 %q 的原因为空", id)
562			}
563			orig, ok := s.Usage[uc.UsageID]
564			if !ok {
565				return fmt.Errorf("用量更正 %q 引用了不存在的原用量 %q（更正来源失效）", id, uc.UsageID)
566			}
567			// 原记录内容不可改写：原用量记录仍须是正常的正数量有效格式（已在
568			// 上面的用量校验中核验），此处仅确认其存在。
569			if orig.ID != uc.UsageID {
570				return fmt.Errorf("用量更正 %q 的原记录标识不一致", id)
571			}
572			if uc.ReplacementID == "" {
573				return fmt.Errorf("用量更正 %q 缺少替代用量标识", id)
574			}
575			if uc.ReplacementID == uc.UsageID {
576				return fmt.Errorf("用量更正 %q 的替代标识与原标识相同", id)
577			}
578			repl, ok := s.Usage[uc.ReplacementID]
579			if !ok {
580				return fmt.Errorf("用量更正 %q 引用了不存在的替代用量 %q（更正目标失效）", id, uc.ReplacementID)
581			}
582			if src, dup := replacementSources[uc.ReplacementID]; dup {
583				return fmt.Errorf("替代用量 %q 同时是用量 %q 与 %q 的更正替代（同一替代记录不得有多个来源）",
584					uc.ReplacementID, src, uc.UsageID)
585			}
586			replacementSources[uc.ReplacementID] = uc.UsageID
587			if _, ok := s.Customers[uc.NewCustomerID]; !ok {
588				return fmt.Errorf("用量更正 %q 引用了不存在的新客户 %q", id, uc.NewCustomerID)
589			}
590			nt, err := time.Parse(time.RFC3339, uc.NewTime)
591			if err != nil {
592				return fmt.Errorf("用量更正 %q 的新时间不是 RFC3339: %w", id, err)
593			}
594			if uc.NewQuantity <= 0 {
595				return fmt.Errorf("用量更正 %q 的新数量非正", id)
596			}
597			rt, err := time.Parse(time.RFC3339, repl.Time)
598			if err != nil {
599				return fmt.Errorf("用量更正 %q 的替代记录 %q 时间不是 RFC3339: %w", id, uc.ReplacementID, err)
600			}
601			// 替代记录内容（客户、解析后的时间点、数量）必须与更正保存的新内容一致；
602			// 时间按瞬间比较，Z 与 +08:00 表示同一时刻视为一致。
603			if repl.CustomerID != uc.NewCustomerID || repl.Quantity != uc.NewQuantity || !rt.Equal(nt) {
604				return fmt.Errorf("用量更正 %q 的替代记录 %q 内容与保存的新内容不一致（更正关联损坏）",
605					id, uc.ReplacementID)
606			}
607			// 原记录必须已撤回，且撤回原因就是更正原因。
608			w, ok := s.Withdrawals[uc.UsageID]
609			if !ok {
610				return fmt.Errorf("用量更正 %q 的原用量 %q 未撤回（更正须把原记录按更正原因标记撤回）", id, uc.UsageID)
611			}
612			if w.Reason != uc.Reason {
613				return fmt.Errorf("用量更正 %q 的原用量 %q 撤回原因 %q 与更正原因 %q 不符",
614					id, uc.UsageID, w.Reason, uc.Reason)
615			}
616		}
617		// 关联成环检测：沿“原记录 -> 替代记录”的更正链前进，重复访问即成环。
618		// 合法链必然终止于一条未再被更正的记录。
619		for id := range s.UsageCorrections {
620			seen := map[string]bool{id: true}
621			cur := id
622			for {
623				uc, ok := s.UsageCorrections[cur]
624				if !ok {
625					break // 链终止于未再被更正的记录
626				}
627				if seen[uc.ReplacementID] {
628					return fmt.Errorf("用量更正关联在 %q 处成环（更正链不得成环）", uc.ReplacementID)
629				}
630				seen[uc.ReplacementID] = true
631				cur = uc.ReplacementID
632			}
633		}
634		for key, b := range s.Bills {
635			if b == nil {
636				return fmt.Errorf("账单 %q 的数据为空", key)
637			}
638			if billKey(b.CustomerID, b.Month) != key {
639				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
640			}
641			if _, ok := s.Customers[b.CustomerID]; !ok {
642				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
643			}
644			if !validMonth(b.Month) {
645				return fmt.Errorf("账单 %q 的月份无效", key)
646			}
647			if b.MonthlyFee < 0 {
648				return fmt.Errorf("账单 %q 的月费为负", key)
649			}
650			// 仅月费大于 0 的账单允许空用量明细（无用量也须出账收取月费）。
651			if len(b.Lines) == 0 && b.MonthlyFee == 0 {
652				return fmt.Errorf("账单 %q 没有明细", key)
653			}
654			var qty, fee int64
655			for _, ln := range b.Lines {
656				u, ok := s.Usage[ln.UsageID]
657				if !ok {
658					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
659				}
660				// 已撤回用量不参与结算，账单不得把已撤回记录视为待计费用量。
661				if _, withdrawn := s.Withdrawals[ln.UsageID]; withdrawn {
662					return fmt.Errorf("账单 %q 引用了已撤回的用量 %q", key, ln.UsageID)
663				}
664				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
665					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
666				}
667				if !inMonth(u.Time, b.Month) {
668					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
669				}
670				var err error
671				qty, err = add64(qty, ln.Quantity)
672				if err != nil {
673					return fmt.Errorf("账单 %q 汇总数量溢出", key)
674				}
675				fee, err = add64(fee, ln.LineFee)
676				if err != nil {
677					return fmt.Errorf("账单 %q 汇总金额溢出", key)
678				}
679			}
680			if qty != b.TotalQty {
681				return fmt.Errorf("账单 %q 总数量与明细不符", key)
682			}
683			// 原总金额 = 月费 + 全月用量费；月费不计入逐条用量小计，故明细
684			// 小计之和等于用量费（总金额 − 月费）。月费与总金额均非负，相减
685			// 不会溢出；总金额为负或小于月费时此处必然不符。
686			if usageFee := b.TotalFee - b.MonthlyFee; fee != usageFee {
687				return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费（明细小计合计 %d 分，月费 %d 分，总金额 %d 分）",
688					key, fee, b.MonthlyFee, b.TotalFee)
689			}
690			c := s.Customers[b.CustomerID]
691			switch b.Pricing {
692			case "", "fixed":
693				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
694				// 携带阶梯方案信息、分段或月费。
695				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
696					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
697				}
698				if b.MonthlyFee != 0 {
699					return fmt.Errorf("账单 %q 是固定单价账单但携带月费", key)
700				}
701				for _, ln := range b.Lines {
702					if len(ln.Segments) > 0 {
703						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
704					}
705					lf, err := mul64(ln.Quantity, c.Price)
706					if err != nil {
