722			}
723			// 封账期内不得存在游离于账单之外的有效用量（封账后新增被禁止，
724			// 而已入账记录理应全部在明细中）；已撤回用量不计费用，允许存在
725			// 于已封账月份而不进入账单。
726			for _, u := range s.Usage {
