902			}
903			if _, ok := s.Customers[a.CustomerID]; !ok {
904				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
905			}
906			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
