1237	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
1238	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
1239	// 小计、各档合计与总金额；任何不符都视为数据损坏。
1240	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
1241		if b.PlanID == "" {
1242			return fmt.Errorf("账单 %q 缺少方案标识", key)
1243		}
1244		p, ok := s.Plans[b.PlanID]
1245		if !ok {
1246			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
1247		}
1248		if b.PlanName != p.Name {
1249			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
1250		}
1251		if !tiersEqual(b.PlanTiers, p.Tiers) {
1252			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
1253		}
1254		if b.MonthlyFee != p.MonthlyFee {
1255			return fmt.Errorf("账单 %q 的月费快照与方案 %q 不符", key, b.PlanID)
1256		}
1257		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
1258		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
1259		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
1260			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
1261		}
1262		if b.UnitPrice != 0 {
1263			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
1264		}
1265		if len(b.TierTotals) != len(p.Tiers) {
1266			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
1267		}
1268		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
1269		recs := make([]*usageRecord, len(b.Lines))
1270		for i, ln := range b.Lines {
1271			recs[i] = s.Usage[ln.UsageID]
1272		}
1273		if !sortedByInstant(recs) {
1274			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
1275		}
1276		priced, err := tieredPrice(p.Tiers, recs)
1277		if err != nil {
1278			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
1279		}
1280		for i, ln := range b.Lines {
1281			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
1282				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
1283			}
1284			if ln.LineFee != priced.lines[i].fee {
1285				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
1286			}
1287		}
1288		for i, tt := range b.TierTotals {
1289			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
1290				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
1291			}
1292		}
1293		// 原总金额 = 月费 + 全月用量费；月费不进入分档合计与逐条小计。
1294		wantTotal, err := add64(priced.totalFee, b.MonthlyFee)
1295		if err != nil || wantTotal != b.TotalFee {
1296			return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费", key)
1297		}
1298		return nil
1299	}
