1458	func (s *state) effectivePlanID(cust *customer, month string) string {
1459		planID := cust.PlanID
1460		latest := ""
1461		for _, ch := range s.PlanChanges {
1462			if ch.CustomerID != cust.ID || s.planChangeRevoked(ch.CustomerID, ch.Month) {
1463				continue
1464			}
1465			if ch.Month <= month && ch.Month >= latest {
1466				latest = ch.Month
1467				planID = ch.PlanID
1468			}
1469		}
1470		return planID
