1486	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
1487	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
1488		var list []*adjustment
1489		for _, a := range s.Adjustments {
1490			if a.CustomerID == customerID && a.Month == month {
1491				list = append(list, a)
1492			}
1493		}
1494		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1495		return list
1496	}
1497	
1498	// correctionsFor 返回某收款的全部分配更正，按操作序号升序。
1499	func correctionsFor(s *state, paymentID string) []*correction {
1500		var list []*correction
1501		for _, c := range s.Corrections {
1502			if c.PaymentID == paymentID {
1503				list = append(list, c)
1504			}
1505		}
1506		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1507		return list
1508	}
1509	
1510	// currentAllocations 返回一笔收款当前生效的分配：无更正时为首次登记的
1511	// 原始分配，否则为序号最大（最新）的更正的分配。
1512	func currentAllocations(s *state, p *payment) []paymentAllocation {
1513		var latest *correction
1514		for _, c := range s.Corrections {
1515			if c.PaymentID == p.ID && (latest == nil || c.Seq > latest.Seq) {
1516				latest = c
1517			}
1518		}
1519		if latest != nil {
1520			return latest.Allocations
1521		}
1522		return p.Allocations
1523	}
1524	
1525	// allocAmountFor 返回分配列表中指定月份的金额；无该月分配时为 0。
1526	func allocAmountFor(allocs []paymentAllocation, month string) int64 {
1527		for _, al := range allocs {
1528			if al.Month == month {
1529				return al.Amount
1530			}
1531		}
1532		return 0
1533	}
1534	
1535	// paymentsEverFor 返回历史上曾涉及某客户某月账单的全部收款（首次登记
1536	// 分配或任一次更正的新分配涉及该月，即使后来被更正移出），按操作序号升序。
1537	func paymentsEverFor(s *state, customerID, month string) []*payment {
1538		var list []*payment
1539		for _, p := range s.Payments {
1540			if p.CustomerID != customerID {
1541				continue
1542			}
1543			involved := p.amountFor(month) > 0
1544			if !involved {
1545				for _, c := range s.Corrections {
1546					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
1547						involved = true
1548						break
1549					}
1550				}
1551			}
1552			if involved {
1553				list = append(list, p)
1554			}
1555		}
1556		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1557		return list
1558	}
1559	
1560	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入并扣除退款后
1561	// 的实收之和。各笔净额（分配减累计退款）均为非负整数，用非负 64 位加法
1562	// 累加，溢出时返回错误。
1563	func paymentReceived(s *state, customerID, month string) (int64, error) {
1564		var received int64
1565		for _, p := range s.Payments {
1566			if p.CustomerID != customerID || p.Revoked {
1567				continue
1568			}
1569			amt := allocAmountFor(currentAllocations(s, p), month) - refundedForMonth(s, p.ID, month)
1570			if amt <= 0 {
1571				continue
1572			}
1573			var err error
1574			received, err = add64(received, amt)
1575			if err != nil {
1576				return 0, err
1577			}
1578		}
1579		return received, nil
1580	}
1581	
1582	// refundsFor 返回某收款的全部退款，按操作序号升序。
1583	func refundsFor(s *state, paymentID string) []*refund {
1584		var list []*refund
1585		for _, r := range s.Refunds {
1586			if r.PaymentID == paymentID {
1587				list = append(list, r)
1588			}
1589		}
1590		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1591		return list
1592	}
1593	
1594	// refundedForMonth 返回某收款在指定月份的累计退款金额（分）；无退款时为 0。
1595	// 数据在载入时已校验累计不超退，合计不超过该月分配，不会溢出。
1596	func refundedForMonth(s *state, paymentID, month string) int64 {
1597		var total int64
1598		for _, r := range s.Refunds {
1599			if r.PaymentID == paymentID {
1600				total += allocAmountFor(r.Allocations, month)
1601			}
1602		}
1603		return total
1604	}
1605	
1606	// paymentHasRefunds 报告某收款是否已发生退款。首次退款后该收款的最新分配
1607	// 固定，不得再新增分配更正或整笔撤销。
1608	func paymentHasRefunds(s *state, paymentID string) bool {
1609		for _, r := range s.Refunds {
1610			if r.PaymentID == paymentID {
1611				return true
1612			}
1613		}
1614		return false
1615	}
1616	
1617	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
1618	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
1619	
1620	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
1621	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
1622	// [0, 有符号 64 位最大值] 内，全程整数运算。
1623	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
1624		var amounts []int64
1625		for _, a := range adjs {
1626			if !a.Revoked {
1627				amounts = append(amounts, a.Amount)
1628			}
1629		}
1630		net, err = sumSigned64(amounts...)
1631		if err != nil {
1632			return 0, 0, err
1633		}
1634		payable, err = addSigned64(b.TotalFee, net)
1635		if err != nil {
1636			return 0, 0, err
1637		}
1638		if payable < 0 {
1639			return 0, 0, errPayableOutOfRange
1640		}
1641		return net, payable, nil
1642	}
1643

