280	func parsePrice(text string) (int64, error) {
281		text = strings.TrimSpace(text)
282		price, err := strconv.ParseInt(text, 10, 64)
283		if err != nil {
284			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
285		}
286		if price < 0 {
287			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
288		}
289		return price, nil
290	}
