418	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
419	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
420		cr := csv.NewReader(r)
421		cr.FieldsPerRecord = 4
422		cr.TrimLeadingSpace = true
423	
424		header, err := cr.Read()
425		if err == io.EOF {
426			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
427		}
428		if err != nil {
429			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
430		}
431		for i := range header {
432			header[i] = strings.TrimSpace(header[i])
433		}
434		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
435			header[2] != "time" || header[3] != "quantity" {
436			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
437		}
438	
439		var rows []*parsedRow
440		var problems []string
441		line := 1
442		for {
443			rec, err := cr.Read()
444			if err == io.EOF {
445				break
446			}
447			line++
448			if err != nil {
449				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
450				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
451					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
452					break
453				}
454				continue
455			}
456			for i := range rec {
457				rec[i] = strings.TrimSpace(rec[i])
458			}
459	
460			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
461			if id == "" {
462				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
463				continue
464			}
465			if custID == "" {
466				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
467				continue
468			}
469			t, err := time.Parse(time.RFC3339, ts)
470			if err != nil {
471				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
472				continue
473			}
474			qty, err := strconv.ParseInt(qtyText, 10, 64)
475			if err != nil {
476				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
477				continue
478			}
479			if qty <= 0 {
480				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
481				continue
482			}
483	
484			rows = append(rows, &parsedRow{
485				line: line,
486				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
487				t:    t,
488			})
489		}
490		return rows, problems
491	}
