493	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
494	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
495	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
496		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
497			return false
498		}
499		et, err := time.Parse(time.RFC3339, existing.Time)
500		if err != nil {
501			return existing.Time == candidate.Time
502		}
503		return et.Equal(candidateT)
504	}
505	
506	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
507	func validMonth(m string) bool {
508		t, err := time.Parse("2006-01", m)
509		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
510			return false
511		}
512		return true
513	}
514	
515	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
516	func inMonth(rfc3339, month string) bool {
517		t, err := time.Parse(time.RFC3339, rfc3339)
518		if err != nil {
519			return false
520		}
521		return t.UTC().Format("2006-01") == month
522	}
523	
524	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
525	// 入参时间均已在载入/导入时校验为 RFC3339。
526	func utcMonth(rfc3339 string) string {
527		t, _ := time.Parse(time.RFC3339, rfc3339)
528		return t.UTC().Format("2006-01")
529	}
