632	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
633	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
634	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
635		lines := make([]billLine, 0, len(recs))
636		var totalQty, totalFee int64
637		for _, u := range recs {
638			lineFee, err := mul64(u.Quantity, cust.Price)
639			if err != nil {
640				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
641			}
642			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
643				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
644			}
645			if totalFee, err = add64(totalFee, lineFee); err != nil {
646				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
647			}
648			lines = append(lines, billLine{
649				UsageID:  u.ID,
650				Time:     u.Time,
651				Quantity: u.Quantity,
652				LineFee:  lineFee,
653			})
654		}
655		return &bill{
656			ID:         stableBillID(cust.ID, month),
657			CustomerID: cust.ID,
658			Month:      month,
659			TotalQty:   totalQty,
660			UnitPrice:  cust.Price,
661			TotalFee:   totalFee,
662			Lines:      lines,
663			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
664		}, nil
665	}
666	
667	func sortByInstant(us []*usageRecord) {
668		// 入参时间均已在载入/导入时校验为 RFC3339。
669		sort.Slice(us, func(i, j int) bool {
670			ti, _ := time.Parse(time.RFC3339, us[i].Time)
671			tj, _ := time.Parse(time.RFC3339, us[j].Time)
672			ui, uj := ti.UTC(), tj.UTC()
673			if !ui.Equal(uj) {
674				return ui.Before(uj)
675			}
676			return us[i].ID < us[j].ID
677		})
678	}
