686	func printBill(b *bill, cust *customer, s *state) {
687		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
688		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
689		// 涉及该月即纳入，即使后来被更正移出。
690		pays := paymentsEverFor(s, b.CustomerID, b.Month)
691		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
692		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
693		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
694		tiered := b.Pricing == "tiered"
695		if tiered {
696			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
697			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
698			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
699			fmt.Fprintln(stdout, "阶梯规则：")
700			for i, t := range b.PlanTiers {
701				if t.Limit == 0 {
702					fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
703				} else {
704					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
705				}
706			}
707		} else {
708			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
709		}
710		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
711		if tiered {
712			// 阶梯账单分列月费与用量费：原总金额 = 月费 + 全月用量费；
713			// 月费不计入总数量、各档金额或逐条小计。
714			usageFee := b.TotalFee - b.MonthlyFee
715			fmt.Fprintf(stdout, "月费：%d 分（%s，整月收取，不按天折算）\n", b.MonthlyFee, moneyFen(b.MonthlyFee))
716			fmt.Fprintf(stdout, "用量费：%d 分（%s）\n", usageFee, moneyFen(usageFee))
717			fmt.Fprintf(stdout, "原总金额：%d 分（%s，月费加全月用量费）\n", b.TotalFee, moneyFen(b.TotalFee))
718		} else {
719			fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
720		}
721		if tiered {
722			fmt.Fprintln(stdout, "各档合计：")
723			for i, tt := range b.TierTotals {
724				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
725					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
726			}
727		}
728		// 数据在载入时已校验一致，此处计算不会出错。
729		net, payable, _ := billTotals(b, adjs)
730		received, _ := paymentReceived(s, b.CustomerID, b.Month)
731		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
732		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
733		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
734		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
735		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
736		if len(b.Lines) == 0 {
737			fmt.Fprintln(stdout, "明细：无（本账期无用量，仅收取月费）")
738		} else {
739			fmt.Fprintln(stdout, "明细：")
740		}
741		for i, ln := range b.Lines {
742			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
743				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
744			// 阶梯账单逐条展示跨档分段的数量、单价与小计。
745			for j, seg := range ln.Segments {
746				fmt.Fprintf(stdout, "     分段 %d：第 %d 档 数量=%d 单价=%d 分 小计=%d 分（%s）\n",
747					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
748			}
749		}
750		if len(adjs) == 0 {
751			fmt.Fprintln(stdout, "调整与撤销历史：无")
752		} else {
753			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
754			for i, ev := range historyEvents(adjs) {
755				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
756			}
757		}
758		if len(pays) == 0 {
759			fmt.Fprintln(stdout, "收款与撤销历史：无")
760		} else {
761			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
762			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
763				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
764			}
765		}
766	}
