805	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
806	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
807	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
808	// 的最新分配。
809	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
810		type event struct {
811			seq  int64
812			text string
813		}
814		var events []event
815		for _, p := range pays {
816			alloc := p.amountFor(month)
817			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
818				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
819			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
820			running := alloc
821			for _, c := range correctionsFor(s, p.ID) {
822				after := allocAmountFor(c.Allocations, month)
823				if running == 0 && after == 0 {
824					continue // 本次更正不涉及本账单
825				}
826				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
827					c.ID, c.Reason, p.ID, running, after)})
828				running = after
829			}
830			if p.Revoked {
831				// 整笔撤销取消的是撤销时的最新分配。
832				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
833					p.ID, p.RevokeReason, p.ID, p.Total, running)})
834			}
835			// 退款在其发生序号减少本账单实收；退款不可撤销，记录永久保留。
836			for _, r := range refundsFor(s, p.ID) {
837				amt := allocAmountFor(r.Allocations, month)
838				if amt <= 0 {
839					continue // 本次退款不涉及本账单
840				}
841				events = append(events, event{r.Seq, fmt.Sprintf("退款 %s：原因：%s（关联收款 %s，本账单退款 %d 分（%s））",
842					r.ID, r.Reason, p.ID, amt, moneyFen(amt))})
843			}
844		}
845		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
846		out := make([]string, len(events))
847		for i, ev := range events {
848			out[i] = ev.text
849		}
850		return out
851	}
