1083	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
1084		total, err := parsePositiveAmount(totalText)
1085		if err != nil {
1086			return err
1087		}
1088		allocs, err := parseAllocations(allocArgs)
1089		if err != nil {
1090			return err
1091		}
1092		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
1093		var sum int64
1094		for _, al := range allocs {
1095			sum, err = add64(sum, al.Amount)
1096			if err != nil {
1097				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
1098			}
1099		}
1100		if sum != total {
1101			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
1102		}
1103		return registerPayment(dir, customerID, payID, total, note, allocs)
1104	}
