1106	// --- 自动分配汇款（bill remit-auto） ---
1107	
1108	// cmdBillRemitAuto 登记一笔自动分配汇款：调用方只提供客户、收款标识、总金额
1109	// 与备注，月份金额由工具确定——首次登记只选择该客户当前已有账单，按 UTC
1110	// 账期月升序依次偿还当前未收余额（调整、最新收款分配、撤销及退款后的净额），
1111	// 跳过余额为 0 的月份，前一月份还清后才分配下一月，最后一月可部分偿还；
1112	// 不补结算、不跨客户、不留未分配款项。无欠款或总金额超过全部欠款时整笔拒绝。
1113	func cmdBillRemitAuto(dir, customerID, payID, totalText, note string) error {
1114		total, err := parsePositiveAmount(totalText)
1115		if err != nil {
1116			return err
1117		}
1118		if strings.TrimSpace(payID) == "" {
1119			return fmt.Errorf("收款标识不能为空")
1120		}
1121		if strings.TrimSpace(note) == "" {
1122			return fmt.Errorf("收款备注不能为空")
1123		}
1124	
1125		s, err := loadStore(dir)
1126		if err != nil {
1127			return err
1128		}
1129		if _, ok := s.Customers[customerID]; !ok {
1130			return fmt.Errorf("客户标识 %q 不存在", customerID)
1131		}
1132	
1133		if existing, ok := s.Payments[payID]; ok {
1134			// 自动登记按客户、总金额、备注判重：相同请求返回原收款及当前状态，
1135			// 不写盘、不重新分配、不增加序号；已撤销或已退款的仍返回当前状态，
1136			// 不恢复旧分配或已退、已撤销金额。
1137			if existing.Auto && existing.CustomerID == customerID &&
1138				existing.Total == total && existing.Note == note {
1139				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同（自动分配登记），返回原收款及当前状态（不写盘、不重新分配、不增加序号）：\n\n", payID)
1140				printAutoPayment(s, existing)
1141				return nil
1142			}
1143			// 同一标识在自动与显式分配登记间复用拒绝；内容不同同样拒绝。
1144			if !existing.Auto {
1145				return fmt.Errorf("收款标识 %q 已由显式分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1146					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1147			}
1148			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q），拒绝复用",
1149				payID, existing.CustomerID, existing.Total, existing.Note)
1150		}
1151	
1152		// 首次登记的自动分配由 remit-auto 与整批导入共用的 autoAllocate 确定。
1153		allocs, err := autoAllocate(s, customerID, total)
1154		if err != nil {
1155			return err
1156		}
1157	
1158		// 成功保存为一笔普通收款及首次自动分配：占用一个账后全局序号，
1159		// 不按月份拆成多笔；可沿用分配更正、整笔撤销、部分退款及退款后
1160		// 固定分配的规则。
1161		p := &payment{
1162			ID:          payID,
1163			CustomerID:  customerID,
1164			Total:       total,
1165			Note:        note,
1166			Allocations: allocs,
1167			Auto:        true,
1168			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1169		}
1170		s.NextSeq++
1171		p.Seq = s.NextSeq
1172		s.Payments[payID] = p
1173	
1174		// 收款记录、首次分配与序号在同一次原子保存中持久化；保存失败则一切
1175		// 不生效，该收款标识与序号不被占用，可原样重试。
1176		if err := s.save(); err != nil {
1177			delete(s.Payments, payID)
1178			s.NextSeq--
1179			return err
1180		}
1181		fmt.Fprintf(stdout, "已按最早欠款账期自动分配并登记收款 %q（总额 %d 分，%s；一次操作，占用一个账后序号）：\n\n",
1182			payID, total, moneyFen(total))
1183		printAutoPayment(s, p)
1184		return nil
1185	}
