1188	// 状态、首次分配与最新分配，以及这两份分配所涉月份的当前余额。首次分配
1189	// 永久保留；最新分配经更正变化时以最新为准，退款与撤销不改变首次分配。
1190	func printAutoPayment(s *state, p *payment) {
1191		current := currentAllocations(s, p)
1192		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1193		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
