1248	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1249	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1250	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1251		if strings.TrimSpace(payID) == "" {
1252			return fmt.Errorf("收款标识不能为空")
1253		}
1254		if strings.TrimSpace(note) == "" {
1255			return fmt.Errorf("收款备注不能为空")
1256		}
1257		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1258		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1259	
1260		s, err := loadStore(dir)
1261		if err != nil {
1262			return err
1263		}
1264		if _, ok := s.Customers[customerID]; !ok {
1265			return fmt.Errorf("客户标识 %q 不存在", customerID)
1266		}
1267		for _, al := range allocs {
1268			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1269				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1270			}
1271		}
1272	
1273		if existing, ok := s.Payments[payID]; ok {
1274			// 自动与显式分配登记之间不得复用同一收款标识：标识由 bill remit-auto
1275			// 占用时，bill pay / bill remit 一律拒绝（即使内容碰巧相同）。
1276			if existing.Auto {
1277				return fmt.Errorf("收款标识 %q 已由自动分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1278					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1279			}
1280			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1281			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1282			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1283			if samePaymentContent(existing, customerID, total, note, allocs) {
1284				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1285				printPayment(existing, s)
1286				return nil
1287			}
1288			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1289				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1290		}
1291	
1292		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1293		for _, al := range allocs {
1294			b := s.Bills[billKey(customerID, al.Month)]
1295			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1296			if err != nil {
1297				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1298			}
1299			received, err := paymentReceived(s, customerID, al.Month)
1300			if err != nil {
1301				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1302			}
1303			if payable == 0 {
1304				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1305			}
1306			if al.Amount > payable-received {
1307				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1308					al.Amount, payable-received, customerID, al.Month, payable, received)
1309			}
1310		}
1311	
1312		p := &payment{
1313			ID:          payID,
1314			CustomerID:  customerID,
1315			Total:       total,
1316			Note:        note,
1317			Allocations: allocs,
1318			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1319		}
1320		s.NextSeq++
1321		p.Seq = s.NextSeq
1322		s.Payments[payID] = p
1323	
1324		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1325		// 一切不生效，该收款标识不被占用。
1326		if err := s.save(); err != nil {
1327			delete(s.Payments, payID)
1328			s.NextSeq--
1329			return err
1330		}
1331		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1332		printAllocationBalances(s, p, allocs)
1333		fmt.Fprintln(stdout)
1334		printPayment(p, s)
1335		return nil
1336	}
