1347	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1348	func sameAllocations(a, b []paymentAllocation) bool {
1349		if len(a) != len(b) {
1350			return false
1351		}
1352		for _, al := range b {
1353			if allocAmountFor(a, al.Month) != al.Amount {
1354				return false
1355			}
1356		}
1357		return true
1358	}
