1360	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1361	func formatAllocations(allocs []paymentAllocation) string {
1362		parts := make([]string, len(allocs))
1363		for i, al := range allocs {
1364			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1365		}
1366		return strings.Join(parts, ",")
1367	}
