30	//
31	//	payment_id   全局收款标识，非空，与 bill remit-auto 共用，自动与显式
32	//	             分配登记之间不得复用
33	//	customer_id  必须是已登记客户
34	//	total_fen    总金额，正整数人民币分（有符号 64 位整数范围内）
35	//	note         备注，非空（可含逗号，按 CSV 规则加引号）
36	const remitHeader = "payment_id,customer_id,total_fen,note"
37	
38	// remitKey 是自动登记收款的判重三元组：客户、总额、备注。
39	type remitKey struct {
40		customerID string
41		total      int64
42		note       string
43	}
44	
45	// parsedRemitRow 是导入文件中一行解析后的候选汇款。
46	type parsedRemitRow struct {
47		line       int // 文件中的行号（含表头），用于报错定位
48		customerID string
49		payID      string
50		total      int64
51		note       string
52	}
53	
54	// acceptedRemit 是批处理中一笔已接受新增收款的登记结果。
55	type acceptedRemit struct {
56		row    *parsedRemitRow
57		p      *payment
58		allocs []paymentAllocation // 首次分配（== 保存时的 p.Allocations）
59	}
60	
61	// remitRowResult 是一行的分类结果：新增或重复跳过。
62	type remitRowResult struct {
63		row   *parsedRemitRow
64		isNew bool
65		dupOf string // 重复来源说明："存档已有" 或 "本批先前出现"
66		p     *payment
67	}
