69	func cmdBillRemitImport(dir, file string) error {
70		var reader io.ReadCloser
71		var source string
72		if file == "-" {
73			reader = io.NopCloser(os.Stdin)
74			source = "标准输入"
75		} else {
76			f, err := os.Open(file)
77			if err != nil {
78				return fmt.Errorf("无法打开收款文件 %s: %w", file, err)
79			}
80			reader = f
81			source = file
82		}
83		defer reader.Close()
84	
85		rows, parseErrs := parseRemitFile(reader)
86	
87		s, err := loadStore(dir)
88		if err != nil {
89			return err
90		}
91	
92		// 先校验：任何问题都在此阶段收集，全部通过后才整体原子保存，
93		// 保证解析、校验或保存失败时全部业务状态不变。
94		var problems []string
95		problems = append(problems, parseErrs...)
96		if len(rows) == 0 && len(problems) == 0 {
97			problems = append(problems, "文件只有表头：收款导入至少需要一条记录")
98		}
99	
100		// batchNew 记录本批先前已接受的新增收款（它们同时挂在内存的 s.Payments
101		// 上以参与后续行的余额计算，但尚未落盘）；判重时优先于存档识别，使本批
102		// 重复行标注为“本批先前出现”，存档已有记录标注为“存档已有”。
103		batchNew := make(map[string]*payment)
104		var accepted []*acceptedRemit
105		var results []remitRowResult
106	
107		for _, r := range rows {
108			// 格式问题已在解析阶段收集；此处仍对必填项做防御性检查。
109			if r.payID == "" || r.customerID == "" || strings.TrimSpace(r.note) == "" || r.total <= 0 {
110				problems = append(problems, fmt.Sprintf("第 %d 行：字段不合法（标识、客户、非空备注与正整数金额均必需）", r.line))
111				continue
112			}
113			key := remitKey{customerID: r.customerID, total: r.total, note: r.note}
114	
115			// 判重先于余额分配：本批先前出现或存档已有的相同自动登记记录计为
116			// 重复跳过；重复行不重新分配、不占序号，后来新增账单、更正、退款或
117			// 撤销都不阻止相同重放。
118			if prev, ok := batchNew[r.payID]; ok {
119				prevKey := remitKey{customerID: prev.CustomerID, total: prev.Total, note: prev.Note}
120				if prevKey != key {
121					problems = append(problems, fmt.Sprintf("第 %d 行：收款标识 %q 在本批先前已接受但内容不同（先前：客户=%s 总额=%d 备注=%q），拒绝复用",
122						r.line, r.payID, prev.CustomerID, prev.Total, prev.Note))
123					continue
124				}
125				results = append(results, remitRowResult{row: r, isNew: false, dupOf: "本批先前出现", p: prev})
126				continue
127			}
128			if existing, ok := s.Payments[r.payID]; ok {
129				if !existing.Auto {
130					problems = append(problems, fmt.Sprintf("第 %d 行：收款标识 %q 已由显式分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用",
131						r.line, r.payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations)))
132					continue
133				}
134				existKey := remitKey{customerID: existing.CustomerID, total: existing.Total, note: existing.Note}
135				if existKey != key {
136					problems = append(problems, fmt.Sprintf("第 %d 行：收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q），拒绝复用",
137						r.line, r.payID, existing.CustomerID, existing.Total, existing.Note))
138					continue
139				}
140				results = append(results, remitRowResult{row: r, isNew: false, dupOf: "存档已有", p: existing})
141				continue
142			}
143	
144			if _, ok := s.Customers[r.customerID]; !ok {
145				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.customerID))
146				continue
147			}
148	
149			// 全新收款：余额基于原存档及本批前面已接受的新收款（它们已挂到
150			// 内存中的 s.Payments，paymentReceived 会计入），按最早欠款账期
151			// 自动分配；无欠款或金额超出欠款则本行非法，整批拒绝。
152			allocs, err := autoAllocate(s, r.customerID, r.total)
153			if err != nil {
154				problems = append(problems, fmt.Sprintf("第 %d 行：%v", r.line, err))
155				continue
156			}
157	
158			p := &payment{
159				ID:          r.payID,
160				CustomerID:  r.customerID,
161				Total:       r.total,
162				Note:        r.note,
163				Allocations: allocs,
164				Auto:        true,
165				CreatedAt:   time.Now().UTC().Format(time.RFC3339),
166			}
167			// 按首次出现顺序各占一个连续递增的账后全局序号；重复行不占序号。
168			s.NextSeq++
169			p.Seq = s.NextSeq
170			s.Payments[r.payID] = p
171			batchNew[r.payID] = p
172			accepted = append(accepted, &acceptedRemit{row: r, p: p, allocs: allocs})
173			results = append(results, remitRowResult{row: r, isNew: true, p: p})
174		}
175	
176		if len(problems) > 0 {
177			// 内存中挂接的新收款不落盘即随进程退出丢弃；磁盘存档保持原样，
178			// 不占任何新标识或序号，可排除故障后原样重试。
179			return fmt.Errorf("收款整批导入失败，整批未生效（共 %d 个问题）：\n  %s",
180				len(problems), strings.Join(problems, "\n  "))
181		}
182	
183		newCount := len(accepted)
184		if newCount > 0 {
185			// 整批新增记录、分配与序号一次原子保存；保存失败全部业务状态不变。
186			if err := s.save(); err != nil {
187				for _, a := range accepted {
188					delete(s.Payments, a.p.ID)
189				}
190				s.NextSeq -= int64(newCount)
191				return fmt.Errorf("收款整批导入保存失败，整批未生效: %w", err)
192			}
193		}
194	
195		// 完整保存成功（或全为重复不写盘）后才按输入顺序逐行报告。
196		if newCount == 0 {
197			fmt.Fprintf(stdout, "整批自动分配导入完成（%s）：新增 0 笔，重复跳过 %d 行（全部为重复记录，未改写存档）\n",
198				source, len(results))
199		} else {
200			fmt.Fprintf(stdout, "整批自动分配导入完成（%s）：新增 %d 笔，重复跳过 %d 行\n",
201				source, newCount, len(results)-newCount)
202		}
203		for i, res := range results {
204			r := res.row
205			current := currentAllocations(s, res.p)
206			first := res.p.Allocations
207			if res.isNew {
208				fmt.Fprintf(stdout, "  %d. 第 %d 行 新增：收款标识 %s，客户 %s，总额 %d 分（%s），备注：%s\n",
209					i+1, r.line, r.payID, r.customerID, r.total, moneyFen(r.total), r.note)
210			} else {
211				fmt.Fprintf(stdout, "  %d. 第 %d 行 重复跳过（%s，不重新分配、不占序号）：收款标识 %s，客户 %s，总额 %d 分（%s），备注：%s\n",
212					i+1, r.line, res.dupOf, r.payID, r.customerID, r.total, moneyFen(r.total), r.note)
213			}
214			fmt.Fprintf(stdout, "     首次分配：%s\n", formatAllocations(first))
215			if sameAllocations(current, first) {
216				fmt.Fprintf(stdout, "     最新分配：%s（与首次分配相同）\n", formatAllocations(current))
217			} else {
218				fmt.Fprintf(stdout, "     最新分配（经更正，以最新为准）：%s\n", formatAllocations(current))
219			}
220		}
221		return nil
222	}
223	
224	// parseRemitFile 完整读取收款 CSV，做格式层面的解析；业务层面的校验在调用方
225	// 完成。规则与用量导入一致：固定表头、恰好四个字段、整数字段按 64 位解析。
226	func parseRemitFile(r io.Reader) ([]*parsedRemitRow, []string) {
227		cr := csv.NewReader(r)
228		cr.FieldsPerRecord = 4
229		cr.TrimLeadingSpace = true
230	
231		header, err := cr.Read()
232		if err == io.EOF {
233			return nil, []string{"文件为空：首行必须是表头 " + remitHeader}
234		}
235		if err != nil {
236			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, remitHeader)}
237		}
238		for i := range header {
239			header[i] = strings.TrimSpace(header[i])
240		}
241		if len(header) != 4 || header[0] != "payment_id" || header[1] != "customer_id" ||
242			header[2] != "total_fen" || header[3] != "note" {
243			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", remitHeader, strings.Join(header, ","))}
244		}
245	
246		var rows []*parsedRemitRow
247		var problems []string
248		line := 1
249		for {
250			rec, err := cr.Read()
251			if err == io.EOF {
252				break
253			}
254			line++
255			if err != nil {
256				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
257				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
258					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
259					break
260				}
261				continue
262			}
263			for i := range rec {
264				rec[i] = strings.TrimSpace(rec[i])
265			}
266	
267			payID, custID, totalText, note := rec[0], rec[1], rec[2], rec[3]
268			if payID == "" {
269				problems = append(problems, fmt.Sprintf("第 %d 行：收款标识不能为空", line))
270				continue
271			}
272			if custID == "" {
273				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
274				continue
275			}
276			total, perr := strconv.ParseInt(totalText, 10, 64)
277			if perr != nil {
278				problems = append(problems, fmt.Sprintf("第 %d 行：总金额 %q 不是有符号 64 位整数范围内的整数", line, totalText))
279				continue
280			}
281			if total <= 0 {
282				problems = append(problems, fmt.Sprintf("第 %d 行：总金额必须是正整数分，收到 %d", line, total))
283				continue
284			}
285			if strings.TrimSpace(note) == "" {
286				problems = append(problems, fmt.Sprintf("第 %d 行：备注不能为空", line))
287				continue
288			}
289	
290			rows = append(rows, &parsedRemitRow{
291				line:       line,
292				customerID: custID,
293				payID:      payID,
294				total:      total,
295				note:       note,
296			})
297		}
298		return rows, problems
299	}
300	
301	// autoAllocate 是 bill remit-auto 与整批导入共用的自动分配核心：只选择该
302	// 客户当前已有账单，按 UTC 账期月升序依次偿还当前未收余额（调整、最新收款
303	// 分配、撤销及退款后的净额），跳过余额为 0 的月份，前一月份还清后才分配
304	// 下一月，最后一月可部分偿还。不补结算、不跨客户、不留未分配款项；无欠款
305	// 或总金额超过全部欠款时返回错误。
306	//
307	// 每月未收余额 = 当前应付 − 实收，均在 [0, 有符号 64 位最大值] 内；
308	// remaining 从总额（正整数分）起只减不增，各月余额与分配全程整数计算——
309	// 即使全部账单欠款合计超过 64 位上限，分配过程也只涉及不超过总额的中间值，
310	// 不会误拒合法金额。
311	func autoAllocate(s *state, customerID string, total int64) ([]paymentAllocation, error) {
312		var months []string
313		for _, b := range s.Bills {
314			if b.CustomerID == customerID {
315				months = append(months, b.Month)
316			}
317		}
318		sort.Strings(months)
319	
320		remaining := total
321		var allocs []paymentAllocation
322		for _, m := range months {
323			if remaining == 0 {
324				break
325			}
326			b := s.Bills[billKey(customerID, m)]
327			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, m))
328			if err != nil {
329				return nil, fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, m, err)
330			}
331			received, err := paymentReceived(s, customerID, m)
332			if err != nil {
333				return nil, fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, m, err)
334			}
335			outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
336			if outstanding <= 0 {
337				continue // 跳过余额为 0 的月份
338			}
339			amt := outstanding
340			if amt > remaining {
341				amt = remaining // 最后一月可部分偿还
342			}
343			allocs = append(allocs, paymentAllocation{Month: m, Amount: amt})
344			remaining -= amt
345		}
346		if len(allocs) == 0 {
347			return nil, fmt.Errorf("客户 %s 当前没有欠款（全部已存在账单的未收余额均为 0），整笔拒绝；不补结算、不跨客户、不留未分配款项", customerID)
348		}
349		if remaining > 0 {
350			return nil, fmt.Errorf("收款总额 %d 分超过客户 %s 全部已存在账单的欠款合计 %d 分，整笔拒绝；不补结算、不跨客户、不留未分配款项",
351				total, customerID, total-remaining)
352		}
353		return allocs, nil
354	}
