13	// setupRefundBase 登记固定单价客户并结算 2026-09（500 分）与 2026-10（300 分）
14	// 两个账期，再登记一笔跨月汇款 pay1（总额 800 分：2026-09:500、2026-10:300）。
15	func setupRefundBase(h *harness) {
16		h.mustRun("customer", "add", "c1", "甲方", "100")
17		f := h.writeFile("u.csv", csvHeader+
18			"u1,c1,2026-09-15T10:00:00Z,5\n"+
19			"u2,c1,2026-10-15T10:00:00Z,3\n")
20		h.mustRun("usage", "import", f)
21		h.mustRun("bill", "settle", "c1", "2026-09")
22		h.mustRun("bill", "settle", "c1", "2026-10")
23		h.mustRun("bill", "remit", "c1", "pay1", "800", "九月十月汇款", "2026-09:500", "2026-10:300")
