26	func TestRefundHappyPathAndBalance(t *testing.T) {
27		h := newHarness(t)
28		setupRefundBase(h)
29	
30		out := h.mustRun("bill", "refund", "pay1", "rf1", "多收退回", "2026-09:200", "2026-10:100")
31		for _, want := range []string{
32			"退款标识：rf1", "关联收款：pay1", "原因：多收退回",
33			"月份 2026-09：本次退款 200 分", "剩余可退 300 分",
34			"月份 2026-10：本次退款 100 分", "剩余可退 200 分",
35			"不可撤销",
36		} {
37			if !strings.Contains(out, want) {
38				t.Fatalf("退款成功输出缺少 %q:\n%s", want, out)
39			}
40		}
41	
42		// 退款只减少对应月实收、增加未收，不改变应付。
43		out = h.mustRun("bill", "show", "c1", "2026-09")
44		for _, want := range []string{
45			"当前应付：500 分", "实收：300 分", "未收余额：200 分",
46			"退款 rf1：原因：多收退回（关联收款 pay1，本账单退款 200 分",
47		} {
48			if !strings.Contains(out, want) {
49				t.Fatalf("bill show(2026-09) 缺少 %q:\n%s", want, out)
50			}
