53		for _, want := range []string{"当前应付：300 分", "实收：200 分", "未收余额：100 分", "退款 rf1"} {
54			if !strings.Contains(out, want) {
55				t.Fatalf("bill show(2026-10) 缺少 %q:\n%s", want, out)
56			}
57		}
58		// 原收款总额、备注、原始分配永久保留。
59		out = h.mustRun("bill", "show", "c1", "2026-09")
60		if !strings.Contains(out, "收款 pay1：总额 800 分") {
61			t.Fatalf("原收款总额未保留:\n%s", out)
62		}
63	}
