259	func mutateState(t *testing.T, h *harness, fn func(map[string]any)) {
260		t.Helper()
261		data, err := os.ReadFile(h.statePath())
262		if err != nil {
263			t.Fatal(err)
264		}
265		var doc map[string]any
266		if err := json.Unmarshal(data, &doc); err != nil {
267			t.Fatal(err)
268		}
269		fn(doc)
270		out, err := json.Marshal(doc)
271		if err != nil {
272			t.Fatal(err)
273		}
274		if err := os.WriteFile(h.statePath(), out, 0o644); err != nil {
275			t.Fatal(err)
276		}
