	if msg := h.runExpectErr("bill", "correct", "pay1", "corr2", "再次更正", "2026-09:500", "2026-10:300"); !strings.Contains(msg, "已固定") {
		t.Fatal(msg)
	}
	if msg := h.runExpectErr("bill", "unpay", "pay1", "整笔退回"); !strings.Contains(msg, "已固定") {
