	}
	// 已有收款、更正的相同重放仍成功，不恢复已退金额或旧分配。
	if out := h.mustRun("bill", "remit", "c1", "pay1", "800", "九月十月汇款", "2026-09:500", "2026-10:300"); !strings.Contains(out, "返回已保存记录") {
