func TestRefundUsageErrors(t *testing.T) {
	h := newHarness(t)
	// 参数数量错误是用法错误（退出码 2）；空清单属于业务错误（退出码 1）。
	for _, args := range [][]string{
		{"bill", "refund"},
		{"bill", "refund", "pay1", "rf1"},
	} {
		_, err := h.run(args...)
