251		var events []ledgerEvent
252		for _, op := range ops {
253			switch op.kind {
254			case pbAdjust, pbAdjustRevoke:
255				e, ok := effectFor(op, b.Month)
256				if !ok {
257					continue
258				}
259				events = append(events, ledgerEvent{
260					seq: op.seq, kind: op.kind, refID: op.refID,
261					deltaPayable: e.deltaPayable, note: op.note, linkSeq: op.linkSeq,
262				})
263			case pbPayment:
264				e, ok := effectFor(op, b.Month)
265				if !ok {
266					continue // 登记时不涉及本账单的收款，不会因后续更正“补登”收款事件
267				}
268				events = append(events, ledgerEvent{
269					seq: op.seq, kind: op.kind, refID: op.refID,
270					deltaReceived: e.deltaReceived, note: op.note,
271					payTotal: op.payTotal, payAlloc: e.alloc,
272				})
273			case pbCorrection:
274				e, ok := effectFor(op, b.Month)
275				if !ok {
276					continue // 前后分配都不涉及本账单的更正不列示
277				}
278				events = append(events, ledgerEvent{
279					seq: op.seq, kind: op.kind, refID: op.refID,
280					deltaReceived: e.deltaReceived, note: op.note, payID: op.payID,
281					beforeAlloc: e.beforeAlloc, afterAlloc: e.afterAlloc,
282				})
283			case pbPaymentRevoke:
284				// 曾涉及该账单的收款（登记分配或任一次更正的新分配曾落在本
285				// 月）即使在撤销时已被更正移出，也保留零金额撤销事件。
286				if !paymentEverTouched(ops, op.payID, b.Month) {
287					continue
288				}
289				e, ok := effectFor(op, b.Month)
290				var amt int64
291				if ok {
292					amt = e.alloc // 撤销当时最新分配中本账单的金额；移出后为 0
293				}
294				events = append(events, ledgerEvent{
295					seq: op.seq, kind: op.kind, refID: op.refID,
296					deltaReceived: -amt, note: op.note, linkSeq: op.linkSeq,
297					payTotal: op.payTotal, payAlloc: amt,
298				})
299			case pbRefund:
