314	// paymentEverTouched 报告某收款是否曾在登记或任一次更正中把分配落到指定
315	// 账期（即使后来被更正移出）。零金额撤销事件的保留只依据“曾经涉及”。
316	func paymentEverTouched(ops []postbillOp, payID, month string) bool {
317		for _, op := range ops {
318			if op.payID != payID {
319				continue
320			}
321			switch op.kind {
322			case pbPayment, pbCorrection:
323				if _, ok := effectFor(op, month); ok {
324					return true
325				}
326			}
327		}
328		return false
329	}
