392	
393	// postbillRangeEvents 把客户级账后操作筛选为跨账期报表区间内的操作条目：
394	// 账期范围 [startMonth, endMonth]（包含首尾），序号区间 (startSeq, endSeq]
395	// （起点之后、终点以内）。每次操作只出现一次，只保留落在范围内账期的
396	// 效果项；操作在范围内没有任何账期效果时不列示。
397	//
398	// 撤销收款只按撤销当时最新分配判断是否涉及范围（effects 即最新分配），
399	// 不因曾经涉及范围而增加操作——这是与单账单流水零金额撤销事件的展示
400	// 差异，差异只发生在本筛选层。
401	func postbillRangeEvents(ops []postbillOp, startMonth, endMonth string, startSeq, endSeq int64) []reconEvent {
402		inRange := func(m string) bool { return m >= startMonth && m <= endMonth }
403		var out []reconEvent
404		for _, op := range ops {
405			if op.seq <= startSeq || op.seq > endSeq {
406				continue
407			}
